// payment-init: SELF-CONTAINED Edge Function (paste this whole file into the Supabase dashboard
// editor, or deploy with the CLI). GENERATED by supabase/functions-src/build.mjs: edit the
// sources there, not this file.
// Starts a payment: the server decides the amount and returns a Paystack reference.
// Needs the secret PAYSTACK_SECRET_KEY (SUPABASE_URL and SUPABASE_SERVICE_ROLE_KEY are provided automatically).
//
// EDITED BY HAND in subscription stage S5b and T1 (the build sources are not in the repo). S5b made four changes, T1 a fifth (top-ups refused):
//   1. the Deps.rpc error type carries the SQL error HINT (and realDeps passes it on);
//   2. `subscription` is added to the purpose whitelist in handleInit;
//   3. new function initSubscription() is called for that purpose, ahead of all the old checks;
//   4. new constants PLAN_KEY and SUBSCRIPTION_REASONS (near REF).
// Every other purpose (request, booking, tier_upgrade) takes exactly the old code path. `topup` is refused (T1, below).
// OWNER RULE (subscriptions): a subscription is paid ONLY through Paystack. No wallet balance is ever used, no top-up is
// involved, and the browser never sends an amount. Do not add a wallet option here.
// VR3a (verification rework): one more hand edit, in handleInit: a refusal from payment_prepare carrying the hint `verification_required` is
// returned as 403 { error, reason: "verification_required" }. Nothing else changed.
import { createClient } from "npm:@supabase/supabase-js@2";

// ============================================================
// StreetTasker payments: the logic of the three payment Edge Functions.
// Kept free of Deno-only APIs so it can be unit-tested in Node (see PAYMENTS-HARDENING.md).
//
//   payment-init      logged-in user asks to pay  -> server decides amount, returns a Paystack reference
//   payment-verify    after the Paystack pop-up   -> server asks Paystack if it was really paid, then finalises
//   paystack-webhook  Paystack calls us directly  -> same finalise step, even if the user closed the tab
//
// Money rules live in SQL (sql/messaging-step6a.sql): payment_prepare / payment_finalize.
// These functions only authenticate, talk to Paystack, and call those two functions.
// ============================================================

interface Deps {
  /** Paystack secret key (never sent to the browser) */
  paystackSecret: string;
  /** Verify a Supabase access token. Returns the user or null. */
  getUser(token: string): Promise<{ id: string; email: string | null } | null>;
  /** Call a Postgres function with the service role */
  rpc(name: string, args: Record<string, unknown>): Promise<{ data: any; error: { code?: string; message: string; hint?: string } | null }>;
  /** Read one payment intent by reference (service role) */
  getIntent(reference: string): Promise<{ user_id: string; status: string; result: any } | null>;
  fetchImpl: typeof fetch;
}

const CORS: Record<string, string> = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
};

function json(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), { status, headers: { ...CORS, "Content-Type": "application/json" } });
}
function preflight(): Response { return new Response("ok", { headers: CORS }); }

const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const REF = /^ST-[0-9a-f]{32}$/i;
// S5b: a plan key is a short lower-case word with underscores (the real list lives in subscription_plans, never here).
const PLAN_KEY = /^[a-z][a-z_]{2,19}$/;
// The refusal reasons subscription_payment_prepare can raise (SQL HINT). Anything else is not passed on.
const SUBSCRIPTION_REASONS = new Set(["unknown_plan", "plan_is_free", "plan_not_available", "not_a_tasker", "local_tasker", "already_on_plan", "use_downgrade", "no_amount_due"]);

function bearer(req: Request): string | null {
  const h = req.headers.get("authorization") || "";
  const m = /^Bearer\s+(.+)$/i.exec(h);
  return m ? m[1].trim() : null;
}

/** Raised by our own SQL (RAISE EXCEPTION) -> safe to show to the user. Anything else is hidden. */
function userFacing(error: { code?: string; message: string }): { status: number; message: string } {
  if (error.code === "P0001") return { status: 400, message: error.message };
  console.error("[payments] unexpected database error:", error.code, error.message);
  return { status: 500, message: "Something went wrong. Please try again." };
}

async function authed(req: Request, deps: Deps) {
  const token = bearer(req);
  if (!token) return null;
  return await deps.getUser(token);
}

// ── payment-init: subscriptions (S5b) ─────────────────────────
// Paid ONLY through Paystack. The browser sends the plan key and nothing else: the price, the credit for unused days and
// the amount all come from the database (subscription_payment_prepare). No wallet balance is read or used, and no
// top-up is created.
async function initSubscription(user: { id: string; email: string | null }, body: any, deps: Deps): Promise<Response> {
  const plan = typeof body?.plan === "string" ? body.plan : "";
  if (!PLAN_KEY.test(plan)) return json({ error: "That plan does not exist.", reason: "unknown_plan" }, 400);
  // Paystack's pop-up needs an email; stop before a payment row exists rather than after.
  if (!user.email) return json({ error: "Your account has no email address, which Paystack needs. Please add one and try again." }, 400);

  const { data, error } = await deps.rpc("subscription_payment_prepare", { p_user: user.id, p_plan: plan });
  if (error) {
    if (error.code === "28000") return json({ error: "Please log in to continue." }, 401);
    const e = userFacing(error);
    const reason = e.status === 400 && error.hint && SUBSCRIPTION_REASONS.has(error.hint) ? error.hint : undefined;
    return json(reason ? { error: e.message, reason } : { error: e.message }, e.status);
  }
  if (!data || typeof data.reference !== "string") {
    console.error("[payments] subscription_payment_prepare returned no reference");
    return json({ error: "Something went wrong. Please try again." }, 500);
  }
  return json({
    reference: data.reference, amount: data.amount, amountKobo: data.amount_kobo,
    email: user.email, purpose: "subscription", bookingId: null, requestId: null, tier: null, capacity: null,
    plan: data.plan, planName: data.plan_name, kind: data.kind, fromPlan: data.from_plan,
    priceKobo: data.price_kobo, creditKobo: data.credit_kobo, netKobo: data.net_kobo,
    periodStart: data.period_start, periodEnd: data.period_end,
  });
}

// ── payment-init ─────────────────────────────────────────────
async function handleInit(req: Request, deps: Deps): Promise<Response> {
  if (req.method === "OPTIONS") return preflight();
  if (req.method !== "POST") return json({ error: "Method not allowed" }, 405);

  const user = await authed(req, deps);
  if (!user) return json({ error: "Please log in to continue." }, 401);

  let body: any;
  try { body = await req.json(); } catch { return json({ error: "Invalid request." }, 400); }

  const purpose = String(body?.purpose || "");
  if (!["request", "booking", "topup", "tier_upgrade", "subscription"].includes(purpose)) return json({ error: "Unknown payment type." }, 400);
  if (purpose === "subscription") return await initSubscription(user, body, deps);
  // T1 (owner rule R-W): the site does not accept top-ups. Refused here, before any payment row exists.
  if (purpose === "topup") return json({ error: "Wallet top-ups are not available." }, 400);
  if (purpose === "request" && !UUID.test(String(body.requestId || ""))) return json({ error: "Missing payment request." }, 400);
  if (purpose === "booking" && !UUID.test(String(body.bookingId || ""))) return json({ error: "Missing booking." }, 400);
  const amount: number | null = null;   // T1: no browser amount is ever used

  const { data, error } = await deps.rpc("payment_prepare", {
    p_user: user.id,
    p_purpose: purpose,
    p_request: purpose === "request" ? body.requestId : null,
    p_booking: purpose === "booking" ? body.bookingId : null,
    p_amount: amount,
  });
  if (error) {
    // VR3a: an unverified customer whose payments would go over the limit. 403 + a stable reason so the page can show the Verify dialog.
    if (error.hint === "verification_required" || /need identity verification/i.test(error.message)) {
      return json({ error: error.message, reason: "verification_required" }, 403);
    }
    const e = userFacing(error); return json({ error: e.message }, e.status);
  }

  // amount comes ONLY from the database; the browser's number (if any) was never used for requests/bookings.
  // tier_upgrade (Stage 7H): the browser sends NOTHING but the purpose; the tier and price come from coordinator_tier_terms(current + 1).
  return json({
    reference: data.reference, amount: data.amount, amountKobo: data.amount_kobo,
    email: user.email, purpose: data.purpose, bookingId: data.booking_id, requestId: data.request_id,
    tier: data.tier, capacity: data.capacity,
  });
}

// ── payment-verify ───────────────────────────────────────────
async function handleVerify(req: Request, deps: Deps): Promise<Response> {
  if (req.method === "OPTIONS") return preflight();
  if (req.method !== "POST") return json({ error: "Method not allowed" }, 405);

  const user = await authed(req, deps);
  if (!user) return json({ error: "Please log in to continue." }, 401);

  let body: any;
  try { body = await req.json(); } catch { return json({ error: "Invalid request." }, 400); }
  const reference = String(body?.reference || "");
  if (!REF.test(reference)) return json({ error: "Invalid payment reference." }, 400);

  const intent = await deps.getIntent(reference);
  if (!intent || intent.user_id !== user.id) return json({ error: "Payment not found." }, 404);
  if (intent.status === "paid") return json({ ...(intent.result || {}), ok: true, already: true });

  let ps: any;
  try {
    const r = await deps.fetchImpl(`https://api.paystack.co/transaction/verify/${encodeURIComponent(reference)}`, {
      headers: { Authorization: `Bearer ${deps.paystackSecret}` },
    });
    ps = await r.json();
    if (!r.ok && !ps) throw new Error("bad response");
  } catch (e) {
    console.error("[payments] Paystack verify failed:", (e as Error).message);
    return json({ ok: false, error: "Could not reach Paystack to confirm the payment. Please try again in a moment." }, 502);
  }

  const d = ps?.data;
  if (!ps?.status || !d) {
    // Paystack does not know this reference (yet): the customer may not have completed it
    return json({ ok: false, pending: true, error: "Payment not confirmed yet." }, 202);
  }
  if (d.reference !== reference) return json({ ok: false, error: "Payment reference mismatch." }, 409);
  if (d.status === "failed") {
    await deps.rpc("payment_mark_failed", { p_reference: reference });
    return json({ ok: false, error: "The payment failed. You have not been charged." }, 402);
  }
  if (d.status !== "success") {
    return json({ ok: false, pending: true, error: "Payment not confirmed yet." }, 202);
  }

  const { data, error } = await deps.rpc("payment_finalize", {
    p_reference: reference, p_paid_kobo: d.amount, p_currency: d.currency,
  });
  if (error) { const e = userFacing(error); return json({ ok: false, error: e.message }, e.status); }
  if (!data?.ok) return json({ ok: false, needs_review: data?.needs_review === true ? true : undefined, error: data?.error || "Payment could not be completed." }, 409);
  return json({ ...data, ok: true });
}

// ── paystack-webhook ─────────────────────────────────────────
function hex(buf: ArrayBuffer): string {
  return Array.from(new Uint8Array(buf)).map((b) => b.toString(16).padStart(2, "0")).join("");
}
async function hmacSha512Hex(secret: string, message: string): Promise<string> {
  const enc = new TextEncoder();
  const key = await crypto.subtle.importKey("raw", enc.encode(secret), { name: "HMAC", hash: "SHA-512" }, false, ["sign"]);
  return hex(await crypto.subtle.sign("HMAC", key, enc.encode(message)));
}
function safeEqual(a: string, b: string): boolean {
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
}

async function handleWebhook(req: Request, deps: Deps): Promise<Response> {
  if (req.method !== "POST") return json({ error: "Method not allowed" }, 405);
  const raw = await req.text();                                  // the signature is over the exact raw body
  const sig = (req.headers.get("x-paystack-signature") || "").toLowerCase();
  const expected = await hmacSha512Hex(deps.paystackSecret, raw);
  if (!sig || !safeEqual(sig, expected)) return json({ error: "Invalid signature" }, 401);

  let evt: any;
  try { evt = JSON.parse(raw); } catch { return json({ error: "Invalid body" }, 400); }
  if (evt?.event !== "charge.success") return json({ ok: true, ignored: true });

  const d = evt.data || {};
  const reference = String(d.reference || "");
  if (!REF.test(reference)) return json({ ok: true, ignored: true });   // not one of ours (e.g. gift cards)

  const { data, error } = await deps.rpc("payment_finalize", {
    p_reference: reference, p_paid_kobo: d.amount, p_currency: d.currency,
  });
  if (error) { console.error("[webhook] finalize error:", error.message); return json({ error: "retry" }, 500); }  // Paystack retries on 5xx
  if (!data?.ok) console.error("[webhook] not finalised:", reference, data?.error);
  return json({ ok: true });
}

// Real dependencies for the payment Edge Functions (Deno + Supabase).

function realDeps(): Deps {
  const url = Deno.env.get("SUPABASE_URL")!;
  const serviceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
  const paystackSecret = Deno.env.get("PAYSTACK_SECRET_KEY") || "";
  if (!paystackSecret) console.error("PAYSTACK_SECRET_KEY is not set. Run: supabase secrets set PAYSTACK_SECRET_KEY=sk_...");

  const admin = createClient(url, serviceKey, { auth: { persistSession: false, autoRefreshToken: false } });

  return {
    paystackSecret,
    fetchImpl: fetch,
    async getUser(token) {
      const { data, error } = await admin.auth.getUser(token);
      if (error || !data?.user) return null;
      return { id: data.user.id, email: data.user.email ?? null };
    },
    async rpc(name, args) {
      const { data, error } = await admin.rpc(name, args);
      return { data, error: error ? { code: error.code, message: error.message, hint: (error as any).hint } : null };
    },
    async getIntent(reference) {
      const { data } = await admin.from("payment_intents").select("user_id,status,result").eq("reference", reference).maybeSingle();
      return data ?? null;
    },
  };
}

const deps = realDeps();
Deno.serve((req: Request) => handleInit(req, deps));